package com.rohit.inventory.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="stock_transfer_items") public class StockTransferItem extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="stock_transfer_id",nullable=false) private StockTransfer transfer; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id",nullable=false) private Product product; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="source_zone_id",nullable=false) private WarehouseZone sourceZone; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="destination_zone_id",nullable=false) private WarehouseZone destinationZone; @Column(name="requested_quantity",nullable=false) private BigDecimal requestedQuantity; @Column(name="approved_quantity",nullable=false) private BigDecimal approvedQuantity=BigDecimal.ZERO; @Column(name="picked_quantity",nullable=false) private BigDecimal pickedQuantity=BigDecimal.ZERO; @Column(name="dispatched_quantity",nullable=false) private BigDecimal dispatchedQuantity=BigDecimal.ZERO; @Column(name="received_quantity",nullable=false) private BigDecimal receivedQuantity=BigDecimal.ZERO; public StockTransfer getTransfer(){return transfer;} public Product getProduct(){return product;} public WarehouseZone getSourceZone(){return sourceZone;} public WarehouseZone getDestinationZone(){return destinationZone;} public BigDecimal getRequestedQuantity(){return requestedQuantity;} public BigDecimal getApprovedQuantity(){return approvedQuantity;} public BigDecimal getPickedQuantity(){return pickedQuantity;} public BigDecimal getDispatchedQuantity(){return dispatchedQuantity;} public BigDecimal getReceivedQuantity(){return receivedQuantity;} public void setTransfer(StockTransfer v){transfer=v;} public void setProduct(Product v){product=v;} public void setSourceZone(WarehouseZone v){sourceZone=v;} public void setDestinationZone(WarehouseZone v){destinationZone=v;} public void setRequestedQuantity(BigDecimal v){requestedQuantity=v;} public void setApprovedQuantity(BigDecimal v){approvedQuantity=v;} public void setPickedQuantity(BigDecimal v){pickedQuantity=v;} public void setDispatchedQuantity(BigDecimal v){dispatchedQuantity=v;} public void setReceivedQuantity(BigDecimal v){receivedQuantity=v;} }
